sub(p,"""	/** Deletes every access and refresh token a user holds for a client. */""","""	/**
	 * Counts the access tokens that still work, per grant (client and user).
	 * A token works while its row exists and its `exp` claim is in the future.
	 * Keys have the form `${clientId}:${userId}`.
	 */
	async countActiveAccessTokens(clientIds: string[]): Promise<Map<string, number>> {
		const rows = await this.accessTokenRepository.findForClients(clientIds);
		const nowSeconds = Math.floor(Date.now() / 1000);
		const counts = new Map<string, number>();
		for (const { token, clientId, userId } of rows) {
			const payload = decode(token);
			const exp = typeof payload === 'object' && payload !== null ? payload.exp : undefined;
			if (typeof exp !== 'number' || exp <= nowSeconds) continue;
			const key = `${clientId}:${userId}`;
			counts.set(key, (counts.get(key) ?? 0) + 1);
		}
		return counts;
	}

	/** Deletes every access and refresh token of a client, for all users. */
	async revokeAllTokensForClient(
		clientId: string,
	): Promise<{ accessTokens: number; refreshTokens: number }> {
		const [accessTokens, refreshTokens] = await Promise.all([
			this.accessTokenRepository.deleteAllForClient(clientId),
			this.refreshTokenRepository.deleteAllForClient(clientId),
		]);
		return { accessTokens, refreshTokens };
	}

	/** Deletes every access and refresh token a user holds for a client. */""")

